insert into public.training_modules (course_id,title,summary,position) values ((select id from public.training_courses where slug='xero-workflows-for-virtual-assistants'),'Xero Foundations','Set up safe access and customer/supplier workflows.',1) on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='xero-workflows-for-virtual-assistants') and position=1),'xero-organisation-contacts-and-va-access-boundaries','Xero Organisation, Contacts, and VA Access Boundaries','Xero connects contacts, invoices, bills, bank transactions, payroll, reports, and tax settings. A VA should know which organisation they are in and which parts they are authorized to touch before doing finance work.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Understand core Xero data relationships","Maintain clean contact records","Use permissions consistent with the VA role"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Xero connects contacts, invoices, bills, bank transactions, payroll, reports, and tax settings. A VA should know which organisation they are in and which parts they are authorized to touch before doing finance work."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["One Xero organisation represents a business entity file.","Contacts can be customers, suppliers, or both.","Role access should follow least privilege.","Accounting and tax settings are high impact.","History and notes can help investigate changes."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm the correct organisation.","Review assigned permissions.","Search contacts before creating duplicates.","Use approved naming and contact conventions.","Document which tasks require bookkeeper or accountant review.","Avoid organisation-wide setting changes without authority."]},{"type":"callout","title":"Stay inside the role","text":"Xero access does not make the VA a bookkeeper, BAS agent, accountant, payroll officer, or tax adviser."},{"type":"callout","title":"Keep this current","text":"Xero features, plans, payroll, BAS/GST, bank-feed, reconciliation, and reporting interfaces change. Verify current official Xero Australia documentation before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Working in the wrong organisation","Duplicate contacts","Changing tax settings to fix one transaction","Using administrator access unnecessarily","Assuming every menu is within role"]},{"type":"scenario","title":"Practice scenario","text":"You have full Xero access but were hired only for invoice follow-up and receipt organization. Define the safe working scope."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Confirm entity and permissions.","Keep contacts clean.","Limit scope.","Escalate configuration changes."]}]'::jsonb,26,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=26,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='xero-workflows-for-virtual-assistants') and position=1),'sales-invoices-credit-notes-and-customer-follow-up','Sales Invoices, Credit Notes, and Customer Follow-Up','Xero supports invoice creation and payment tracking. A VA can prepare or send approved invoices and follow up balances, but commercial concessions and accounting treatment need authority.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Support approved invoice workflows","Track payment status","Handle credits and overdue follow-up safely"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Xero supports invoice creation and payment tracking. A VA can prepare or send approved invoices and follow up balances, but commercial concessions and accounting treatment need authority."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Invoice status should reflect actual workflow.","Customer, date, due date, line items, amounts, and tax treatment need approved source data.","Credit notes change balances.","Bank receipts or online payments may affect status.","Aged receivables need dispute context."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm approved billing source.","Create or check the invoice.","Route tax or account questions.","Send if authorized.","Check payment status before reminders.","Record customer response or dispute.","Escalate credits, write-offs, payment plans, and pricing decisions."]},{"type":"callout","title":"Stay inside the role","text":"Do not change GST codes, create unauthorized credits, alter prices, or write off invoices to clean aged receivables."},{"type":"callout","title":"Keep this current","text":"Xero features, plans, payroll, BAS/GST, bank-feed, reconciliation, and reporting interfaces change. Verify current official Xero Australia documentation before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Sending duplicate invoices","Chasing paid customers","Editing tax treatment","Using a credit note as a shortcut","Ignoring dispute history"]},{"type":"scenario","title":"Practice scenario","text":"A customer says they paid yesterday, but Xero still shows the invoice outstanding. Explain the checks before sending another reminder."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Invoice from approved data.","Check status before follow-up.","Treat credits as controlled.","Escalate accounting judgment."]}]'::jsonb,26,2,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=26,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

