insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='xero-workflows-for-virtual-assistants') and position=2),'bills-receipts-and-accounts-payable-in-xero','Bills, Receipts, and Accounts Payable in Xero','Bills and source documents feed accounts payable, cash flow, GST/BAS, and reporting. The VA''s job is clean capture and exception routing.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Enter supplier bills from evidence","Prevent duplicates","Track approval and payment handoff"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Bills and source documents feed accounts payable, cash flow, GST/BAS, and reporting. The VA''s job is clean capture and exception routing."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Supplier identity, invoice number, dates, amount, line items, and tax treatment matter.","Duplicate detection needs more than filename.","Attachments preserve evidence.","Approval and payment authority are separate.","Supplier bank-detail changes require verification."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Search supplier/contact.","Check duplicate number, amount, and date.","Enter approved fields.","Attach source document.","Use only approved accounts and tax rates.","Route uncertainty.","Track approval and payment status.","Record evidence after payment."]},{"type":"callout","title":"Stay inside the role","text":"Do not choose tax treatment, approve payment, or accept changed bank details without the client''s verification process."},{"type":"callout","title":"Keep this current","text":"Xero features, plans, payroll, BAS/GST, bank-feed, reconciliation, and reporting interfaces change. Verify current official Xero Australia documentation before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Duplicate bills","Guessing account codes","Accepting emailed bank changes","Marking paid before evidence","Deleting source documents after upload"]},{"type":"scenario","title":"Practice scenario","text":"A supplier bill imports twice through two channels. Describe the checks before deleting, voiding, or matching anything."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Source evidence first.","Prevent duplicates.","Respect approvals.","Keep finance exceptions visible."]}]'::jsonb,26,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=26,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='xero-workflows-for-virtual-assistants') and position=2),'bank-feeds-matching-and-reconciliation-preparation','Bank Feeds, Matching, and Reconciliation Preparation','Xero can import bank data and suggest transaction matches. Current Xero AU materials emphasize bank feeds and reconciliation, but automation does not replace accounting judgment.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Understand Xero bank-feed and reconciliation workflow","Use suggested matches carefully","Prepare exceptions for review"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Xero can import bank data and suggest transaction matches. Current Xero AU materials emphasize bank feeds and reconciliation, but automation does not replace accounting judgment."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Bank-feed transactions show bank activity, not complete accounting classification.","Suggested matches need verification.","Bank rules can automate recurring treatment but must be approved.","Transfers, duplicates, fees, owner transactions, and mixed-purpose items need context.","History and notes can support audit trail."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review bank transaction details.","Search for matching invoice, bill, or transaction.","Check amount, date, reference, and counterparty.","Apply approved bank rules only.","Do not create a new transaction if purpose is unclear.","Flag exceptions for reviewer.","Document resolution."]},{"type":"callout","title":"Stay inside the role","text":"Do not accept AI or software matching solely because confidence is high. Accounting and GST treatment still require correct business context."},{"type":"callout","title":"Keep this current","text":"Xero features, plans, payroll, BAS/GST, bank-feed, reconciliation, and reporting interfaces change. Verify current official Xero Australia documentation before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Clicking OK on every suggestion","Reconciling duplicate imports","Misclassifying transfers","Creating expenses to make the feed disappear","Ignoring unfamiliar high-value transactions"]},{"type":"scenario","title":"Practice scenario","text":"Xero suggests a match between a bank transaction and a bill with a slightly different amount. Explain the evidence you check and when you stop for review."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Suggestions are not authority.","Match from evidence.","Use bank rules carefully.","Escalate uncertain items."]}]'::jsonb,26,2,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=26,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

