insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='xero-workflows-for-virtual-assistants') and position=3),'gst-bas-and-australian-tax-awareness-in-xero','GST, BAS, and Australian Tax Awareness in Xero','Xero AU supports GST tracking and BAS workflows. Ordinary transaction coding can influence compliance reports, so a VA must follow approved rules and preserve review boundaries.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Recognize how transaction coding affects GST and BAS","Prepare review material","Avoid unauthorized tax changes or lodgement"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Xero AU supports GST tracking and BAS workflows. Ordinary transaction coding can influence compliance reports, so a VA must follow approved rules and preserve review boundaries."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["GST treatment flows from transaction setup and coding.","BAS can draw from transaction data.","GST audit and review reports may help inspect underlying transactions.","Business tax settings are high impact.","A VA can gather exceptions without deciding the tax position."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Use approved account and tax settings.","Flag transactions that do not fit known rules.","Attach supporting evidence.","Prepare GST/BAS exception lists.","Run draft reports if authorized.","Route corrections and lodgement decisions to the appropriate qualified or authorized person."]},{"type":"callout","title":"Stay inside the role","text":"Do not determine GST treatment, amend prior periods, lodge BAS, or present yourself as a BAS or tax adviser unless qualified and authorized."},{"type":"callout","title":"Keep this current","text":"Xero features, plans, payroll, BAS/GST, bank-feed, reconciliation, and reporting interfaces change. Verify current official Xero Australia documentation before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Changing GST code to match a total","Treating Xero''s calculation as tax advice","Lodging because the button exists","Correcting prior periods without review","Ignoring private-use complexity"]},{"type":"scenario","title":"Practice scenario","text":"A recurring expense has been coded with GST for months, but a new invoice appears different. Explain the review process."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Transaction coding affects BAS.","Use approved rules.","Prepare evidence.","Keep tax decisions with qualified owners."]}]'::jsonb,26,1,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=26,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='xero-workflows-for-virtual-assistants') and position=3),'payroll-stp-and-payroll-admin-handoffs-in-xero','Payroll, STP, and Payroll-Admin Handoffs in Xero','Xero AU offers payroll and STP features on eligible plans. Payroll combines private employee data with statutory reporting, making role clarity essential.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Recognize Xero payroll and STP workflow","Prepare payroll inputs","Protect sensitive employee data"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Xero AU offers payroll and STP features on eligible plans. Payroll combines private employee data with statutory reporting, making role clarity essential."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Employee details, pay items, leave, super, tax, and payroll calendars feed pay runs.","STP reporting communicates payroll information to the ATO.","Payroll setup affects calculations.","Employee changes need effective dates and approval.","Final declarations and statutory treatment require authorized oversight."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Collect approved timesheets and employee changes.","Check missing approvals.","Prepare payroll exception list.","Use approved pay items and settings only.","Support draft pay-run review.","Route tax, super, leave, award, termination, and STP questions.","Submit or report only under authorized qualified process."]},{"type":"callout","title":"Stay inside the role","text":"Do not change statutory categories, pay rates, tax or super treatment, or submit STP from your own judgment."},{"type":"callout","title":"Keep this current","text":"Xero features, plans, payroll, BAS/GST, bank-feed, reconciliation, and reporting interfaces change. Verify current official Xero Australia documentation before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Changing pay setup from an employee email","Sharing payroll reports openly","Treating Xero calculations as proof setup is correct","Submitting STP without authority","Guessing leave treatment"]},{"type":"scenario","title":"Practice scenario","text":"An employee says their super amount looks wrong after a pay run. Explain what evidence you gather and who owns the decision."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Payroll is sensitive.","Prepare, check, and escalate.","Keep setup decisions controlled.","Separate software steps from statutory authority."]}]'::jsonb,26,2,false,1,null,null,now(),now())
on conflict (module_id,slug) do update set title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=26,position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,content_version=public.training_lessons.content_version+1,updated_at=now();

