insert into public.training_lessons (module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at)
values ((select id from public.training_modules where course_id=(select id from public.training_courses where slug='xero-workflows-for-virtual-assistants') and position=4),'xero-reports-month-end-support-and-composite-simulation','Xero Reports, Month-End Support, and Composite Simulation','Reports such as receivables, payables, profit and loss, balance sheet, and transaction detail depend on underlying records. The VA can support review without presenting reports as final professional conclusions.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Prepare useful draft reports","Trace issues to source transactions","Run a full Xero admin simulation"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Reports such as receivables, payables, profit and loss, balance sheet, and transaction detail depend on underlying records. The VA can support review without presenting reports as final professional conclusions."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Date range and accounting basis matter.","Unreconciled or misclassified items can distort reports.","AP and AR reports need dispute and payment context.","Draft reports should be labeled honestly.","Reviewer questions should link to source transactions."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm reporting period and requested report.","Review known exceptions.","Run the approved draft report.","Investigate surprising items at source level.","Prepare a linked exception list.","Complete the fictional AP, AR, bank-feed, GST, and payroll queue.","Hand off to reviewer with specific questions."]},{"type":"callout","title":"Stay inside the role","text":"Do not present unreviewed Xero outputs as audited, final, tax-compliant, or professionally certified statements."},{"type":"callout","title":"Keep this current","text":"Xero features, plans, payroll, BAS/GST, bank-feed, reconciliation, and reporting interfaces change. Verify current official Xero Australia documentation before publishing or reviewing this lesson."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Changing transactions to make a report look expected","Using the wrong date range","Ignoring unreconciled bank items","Sending a P&L with no context","Asking the reviewer to check everything"]},{"type":"scenario","title":"Practice scenario","text":"A fictional Australian agency has duplicate bills, overdue invoices, three bank-feed suggestions, one unusual GST-coded expense, a payroll adjustment request, and a surprising month-end report. Work through the Xero admin steps and escalation."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Reports reflect source data.","Investigate rather than cosmetically fix.","Label drafts.","Make review efficient."]}]'::jsonb,26,1,false,1,null,null,now(),now())
